// Convierte el payload de Meta en 1 item por mensaje recibido.
// - Recorre TODOS los entry/changes/messages (Meta puede agrupar varios).
// - Ignora los webhooks de estado (sent/delivered/read): devuelve [] y la
//   ejecución termina aquí sin tocar la base de datos.
function extraerTexto(m) {
  switch (m.type) {
    case 'text':        return m.text?.body ?? '';
    case 'button':      return m.button?.text ?? '';
    case 'interactive': return m.interactive?.button_reply?.title
                            ?? m.interactive?.list_reply?.title ?? '[interactive]';
    case 'image':
    case 'video':
    case 'document':    return m[m.type]?.caption || `[${m.type}]`;
    case 'location':    return `[location] ${m.location?.latitude},${m.location?.longitude}`;
    default:            return `[${m.type}]`;   // audio, sticker, reaction, etc.
  }
}

const out = [];
for (const item of $input.all()) {
  for (const entry of item.json.body?.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const v = change.value ?? {};
      if (!Array.isArray(v.messages)) continue;
      const phone_number_id = v.metadata?.phone_number_id ?? '';   // agencia que recibió

      const nombres = {};
      for (const c of v.contacts ?? []) nombres[c.wa_id] = c.profile?.name ?? '';

      for (const m of v.messages) {
        if (m.type === 'reaction') continue;   // no aporta a la conversación
        const nombre = nombres[m.from] ?? '';
        out.push({
          json: {
            wa_message_id: m.id,
            phone_number_id,
            phone: m.from,
            nombre_cliente: nombre,
            tipo: m.type,
            mensaje_cliente: extraerTexto(m),
            ts: Number(m.timestamp) || Math.floor(Date.now() / 1000),
          },
        });
      }
    }
  }
}
return out;

// Los textos de cada agencia (bienvenida, info_terrenos, bot_activo) se
// configuran en la tabla public.whatsapp_lineas. Estos son los textos por
// defecto cuando la agencia no tiene uno propio.
const BIENVENIDA_DEFECTO =
  'Hola {nombre} 👋, gracias por escribir a *{agencia}*.\n' +
  'Por este medio te brindamos información sobre nuestros *terrenos*.\n\n' +
  'Responde *1* o escribe *terrenos* para recibir la información.';

const SALUDO_CORTO = (nombre, agencia) =>
  `Hola${nombre ? ' ' + nombre : ''} 👋, gracias por escribir${agencia ? ' a *' + agencia + '*' : 'nos'}.`;

const FUERA_DE_TEMA =
  'Por este medio solo podemos ayudarte con información sobre nuestros *terrenos*. ' +
  '¿Te gustaría recibirla? Responde *1* o escribe *terrenos*.';

const ASESOR =
  'En un momento un asesor se comunicará contigo para darte más detalles y resolver tus dudas. 🙌';

// Palabras propias del tema terrenos: si aparece alguna, el cliente pide info.
const TEMA = /\b(terrenos?|lotes?|solar(es)?|precios?|costos?|cuanto|cuesta|valor|ubicacion|medidas|metros|m2|hectareas?|financiamiento|credito|cuotas|plano|escrituras?|urbanizacion)\b/;
// Respuestas afirmativas cortas ("1", "sí por favor", "quiero información").
// Solo cuentan si el mensaje NO trae otra cosa: "información sobre el clima"
// deja "clima" sin explicar y se trata como fuera de tema.
const AFIRMATIVAS = new Set(('1 si ok okay claro dale bueno listo perfecto porfa por favor me interesa interesado interesada ' +
  'quiero quisiera deseo dame enviame mandame recibir info informacion mas la el los las de del una un sobre eso esa gracias').split(' '));
const esAfirmativa = (t) => {
  const palabras = t.replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
  return palabras.length > 0 && palabras.every((p) => AFIRMATIVAS.has(p));
};
// =====================================================================

// Etapas del bot (columna leads.bot_stage):
//   NULL        -> lead nuevo, aún no se le saluda
//   bienvenida  -> se envió el saludo, esperando que pida info
//   aclaracion  -> escribió algo fuera de tema una vez
//   asesor      -> se derivó a un asesor; el bot ya NO responde
const normalizar = (t) =>
  (t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const unir = (...partes) => partes.filter(Boolean).join('\n\n');

const out = [];
$input.all().forEach((item, i) => {
  const { lead_id, phone, phone_number_id, bot_stage, mensaje_nuevo, bot_activo } = item.json;
  if (!mensaje_nuevo || !bot_activo || bot_stage === 'asesor') return;   // duplicado, bot apagado o con asesor

  const agencia = item.json.agencia;
  const INFO_TERRENOS = item.json.info_terrenos;
  const BIENVENIDA = (nombre) =>
    (item.json.bienvenida || BIENVENIDA_DEFECTO)
      .replaceAll('{nombre}', nombre || '')
      .replaceAll('{agencia}', agencia || 'nuestra inmobiliaria')
      .replace(/ {2,}/g, ' ');

  const entrada = $('Normalizar mensajes').itemMatching(i).json;
  const nombre = entrada.nombre_cliente;
  const texto = normalizar(entrada.mensaje_cliente);
  const interes = TEMA.test(texto) || esAfirmativa(texto);

  let respuesta, siguiente;
  if (!bot_stage) {
    // Primer mensaje. Si ya pide info ("quiero info de los terrenos"),
    // se saluda y se deriva en un solo mensaje.
    if (interes) { respuesta = unir(SALUDO_CORTO(nombre, agencia), INFO_TERRENOS, ASESOR); siguiente = 'asesor'; }
    else         { respuesta = BIENVENIDA(nombre);                                siguiente = 'bienvenida'; }
  } else if (interes) {
    respuesta = unir(INFO_TERRENOS, ASESOR); siguiente = 'asesor';
  } else if (bot_stage === 'bienvenida') {
    respuesta = FUERA_DE_TEMA;               siguiente = 'aclaracion';
  } else {
    // Segundo mensaje fuera de tema: no insistir, pasar a un asesor.
    respuesta = ASESOR;                      siguiente = 'asesor';
  }

  out.push({
    json: { lead_id, phone, phone_number_id, etapa_actual: bot_stage ?? '', siguiente_etapa: siguiente, respuesta },
    pairedItem: { item: i },
  });
});
return out;

